class Solution {
public:
    long long minimumTotalDistance(std::vector<int>& robot, std::vector<std::vector<int>>& factory) {
        std::sort(robot.begin(), robot.end());
        std::sort(factory.begin(), factory.end(), [](const auto& a, const auto& b) { return a[0] < b[0]; });
        std::vector<int> slots;
        for (const auto& f : factory) {
            for (int k = 0; k < f[1]; ++k) slots.push_back(f[0]);
        }
        int n = robot.size(), m = slots.size();
        const long long INF = 1e16;
        std::vector<long long> prev(m + 1, 0);
        for (int i = 1; i <= n; ++i) {
            std::vector<long long> cur(m + 1, INF);
            for (int j = i; j <= m; ++j) {
                cur[j] = std::min(cur[j - 1], prev[j - 1] + std::abs((long long)robot[i - 1] - slots[j - 1]));
            }
            prev = std::move(cur);
        }
        return prev[m];
    }
};

class Solution {
    public long minimumTotalDistance(java.util.List<Integer> robot, int[][] factory) {
        java.util.Collections.sort(robot);
        java.util.Arrays.sort(factory, (a, b) -> Integer.compare(a[0], b[0]));
        java.util.List<Integer> slots = new java.util.ArrayList<>();
        for (int[] f : factory) {
            for (int k = 0; k < f[1]; k++) slots.add(f[0]);
        }
        int n = robot.size(), m = slots.size();
        long INF = (long) 1e16;
        long[] prev = new long[m + 1];
        for (int i = 1; i <= n; i++) {
            long[] cur = new long[m + 1];
            java.util.Arrays.fill(cur, INF);
            for (int j = i; j <= m; j++) {
                cur[j] = Math.min(cur[j - 1], prev[j - 1] + Math.abs((long)robot.get(i - 1) - slots.get(j - 1)));
            }
            prev = cur;
        }
        return prev[m];
    }
}

var minimumTotalDistance = function(robot, factory) {
    robot.sort((a, b) => a - b);
    factory.sort((a, b) => a[0] - b[0]);
    const slots = [];
    for (const [pos, cap] of factory) {
        for (let k = 0; k < cap; k++) slots.push(pos);
    }
    const n = robot.length, m = slots.length;
    const INF = 1e16;
    let prev = new Array(m + 1).fill(0);
    for (let i = 1; i <= n; i++) {
        const cur = new Array(m + 1).fill(INF);
        for (let j = i; j <= m; j++) {
            cur[j] = Math.min(cur[j - 1], prev[j - 1] + Math.abs(robot[i - 1] - slots[j - 1]));
        }
        prev = cur;
    }
    return prev[m];
};
